"""Lineview load test.

Each simulated user logs in as one real seeded user (one token from tokens.json), then
repeatedly asks for the defect rate by product over a random window of the data's date range.
Every response is checked: all rows must carry the tenant_id and user belongs to.
A row from another tenant is reported as a LEAK failure
"""

import json
import os
import random
from datetime import datetime, timedelta, timezone

from locust import HttpUser, between, task

# tokens.json is generated by the loader into ../loadtest/ (not in version control).
# In compose, TOKENS_PATH points at the mounted copy.
TOKENS_PATH = os.environ.get(
    "TOKENS_PATH",
    os.path.join(
        os.path.dirname(os.path.abspath(__file__)), "..", "loadtest", "tokens.json"
    ),
)

if not os.path.exists(TOKENS_PATH):
    raise SystemExit(
        f"{TOKENS_PATH} not found. The loader generates it, and it is the only copy of the"
        "plaintext tokens (the DB stores hashes). Create it with: "
        "docker compuse run --build --rm loader -reset (this reloads all data)"
    )

with open(TOKENS_PATH) as f:
    TOKENS = json.load(f)

# The loader's fixed window: 2026-01-01 plus 270 days.
DATA_START = datetime(2026, 1, 1, tzinfo=timezone.utc)
DATA_DAYS = 270
WINDOW_DAYS = int(os.environ.get("WINDOW_DAYS", "7"))


def rfc3339(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


class TenantUser(HttpUser):
    wait_time = between(0.2, 1.0)

    def on_start(self):
        ident = random.choice(TOKENS)
        self.tenant = ident["tenant"]
        self.tenant_id = ident["tenant_id"]
        self.client.cookies.set("session", ident["token"])

    @task
    def defect_rate_by_product(self):
        start = DATA_START + timedelta(days=random.randint(0, DATA_DAYS - WINDOW_DAYS))
        params = {
            "from": rfc3339(start),
            "to": rfc3339(start + timedelta(days=WINDOW_DAYS)),
        }

        # name = groups the stats per tenant, so each tenant's latency shows up separately.
        with self.client.get(
            "/api/defect-rate/products",
            params=params,
            name=f"defect-rate [{self.tenant}]",
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"HTTP {resp.status_code}")
                return
            try:
                rows = resp.json() or []
            except ValueError:
                resp.failure("invalid JSON")
                return

            foreign = {r["tenant_id"] for r in rows} - {self.tenant_id}
            if foreign:
                resp.failure(
                    f"LEAK: user of {self.tenant_id} also saw {sorted(foreign)}"
                )
            else:
                resp.success()
